#include <stdio.h>
#include <stdlib.h>

#define MAXN 200005
#define MAXM 400005

static int parent[MAXN];
static long long szv[MAXN];
static long long ecnt[MAXN];
static int deg[MAXN];
static int head[MAXN];
static int enext[2 * MAXM];
static int eto[2 * MAXM];
static int stampArr[MAXN];
static int ex[MAXM], ey[MAXM];

static int find(int x) {
    int r = x;
    while (parent[r] != r) r = parent[r];
    while (parent[x] != r) {
        int nx = parent[x];
        parent[x] = r;
        x = nx;
    }
    return r;
}

int main(void) {
    int n, m;
    if (scanf("%d %d", &n, &m) != 2) return 0;

    for (int i = 1; i <= n; i++) {
        parent[i] = i;
        szv[i] = 1;
        head[i] = -1;
    }

    for (int e = 0; e < m; e++) {
        int x, y;
        scanf("%d %d", &x, &y);
        ex[e] = x;
        ey[e] = y;
        deg[x]++;
        deg[y]++;

        int i2 = e * 2;
        eto[i2] = y; enext[i2] = head[x]; head[x] = i2;
        eto[i2 + 1] = x; enext[i2 + 1] = head[y]; head[y] = i2 + 1;

        int rx = find(x), ry = find(y);
        if (rx != ry) {
            if (szv[rx] < szv[ry]) { int t = rx; rx = ry; ry = t; }
            parent[ry] = rx;
            szv[rx] += szv[ry];
        }
    }

    /* contar arestas por componente */
    for (int e = 0; e < m; e++) ecnt[find(ex[e])]++;

    /* procurar componente que nao seja clique */
    int root = -1;
    long long S = 0;
    for (int i = 1; i <= n; i++) {
        int r = find(i);
        if (szv[r] * (szv[r] - 1) / 2 > ecnt[r]) {
            root = r;
            S = szv[r];
            break;
        }
    }

    if (root == -1) {
        printf("-1\n");
        return 0;
    }

    /* vertice v no componente com grau < S-1 (existe, pois nao e clique) */
    int v = -1;
    for (int i = 1; i <= n; i++) {
        if (find(i) == root && deg[i] != S - 1) { v = i; break; }
    }
    if (v == -1) {
        printf("-1\n");
        return 0;
    }

    /* marcar vizinhos de v */
    int cur = ++stampArr[0];
    for (int e = head[v]; e != -1; e = enext[e]) stampArr[eto[e]] = cur;

    /* procurar u no mesmo componente nao adjacente a v */
    for (int i = 1; i <= n; i++) {
        if (find(i) == root && i != v && stampArr[i] != cur) {
            printf("%d %d\n", v, i);
            return 0;
        }
    }

    printf("-1\n");
    return 0;
}
